begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('77000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(1),'role','authenticated','session_id',pg_temp.i(1))::text,true);
create function pg_temp.ctx() returns jsonb language sql stable as $$select jsonb_build_object('organizationId',organization_id,'branchId',id) from public.branches where code='B01'$$;
create function pg_temp.sale(n integer,pc integer,q text default '1') returns jsonb language sql stable as $$select pg_temp.ctx()||jsonb_build_object('version',1,'transactionId',pg_temp.i(n),'cashierId',auth.uid(),'deviceId',pg_temp.i(pc),'shiftId',(select id from public.cashier_shifts where device_id=pg_temp.i(pc) and closed_at is null),'occurredAt',to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'total',q::numeric*10000-100,'cashReceived',q::numeric*10000,'items',jsonb_build_array(jsonb_build_object('productId',p.id,'unitId',u.id,'batchId',null,'name',p.name,'unitName',u.name,'quantity',q,'factor','1','unitPrice',10000,'unitCost',5000,'priceVersion',1,'discountAmount',100,'lineTotal',q::numeric*10000-100))) from public.products p join public.product_units u on u.product_id=p.id where p.sku='MULTI'$$;
set local role authenticated;
select public.agri_command('bootstrap','{"name":"TEST multiple PCs","ownerName":"TEST owner"}');
select public.agri_command('create_product',pg_temp.ctx()||'{"name":"TEST shared packets","sku":"MULTI","category":"Seeds","baseUnit":"piece","minimumStock":"0","units":[{"name":"Packet","factor":"1","price":10000,"cost":5000}]}');
select public.agri_command('receive_stock',pg_temp.ctx()||jsonb_build_object('receiptId',pg_temp.i(10),'source','purchase','reference','TEST three packets','items',(select jsonb_build_array(jsonb_build_object('productId',p.id,'unitId',u.id,'quantity','3')) from public.products p join public.product_units u on u.product_id=p.id where p.sku='MULTI')));
select public.agri_command('register_device',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(11),'name','TEST drawer A'));
select public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(11),'openingCash',500));
select public.agri_command('close_shift',pg_temp.ctx()||jsonb_build_object('shiftId',(select id from public.cashier_shifts where closed_at is null),'countedCash',500));
select public.agri_command('close_shift',pg_temp.ctx()||jsonb_build_object('shiftId',(select id from public.cashier_shifts where device_id=pg_temp.i(11) and closed_at is null),'countedCash',10900));
select public.agri_command('close_shift',pg_temp.ctx()||jsonb_build_object('shiftId',(select id from public.cashier_shifts where device_id=pg_temp.i(12) and closed_at is null),'countedCash',11900));
reset role;
select line from tap_results;
rollback;
