insert into auth.users(id,email) values(pg_temp.i(1),'multi-owner@example.invalid');
insert into auth.sessions(id,user_id) values(pg_temp.i(1),pg_temp.i(1));
insert into tap_results select throws_ok($$select public.agri_command('register_device',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(12),'name','TEST drawer B'))$$,'23505',null,'Single-PC branches retain their registration guard');
insert into tap_results select throws_ok($$select public.agri_command('configure_cashier_pcs',pg_temp.ctx()||'{"enabled":true,"reason":"TEST shared checkout"}')$$,'P0001','Close and synchronize every branch shift before changing cashier PC mode','Mode change cannot bypass an open drawer');
insert into tap_results select lives_ok($$select public.agri_command('configure_cashier_pcs',pg_temp.ctx()||'{"enabled":true,"reason":"TEST shared checkout"}')$$,'Owner enables online multiple-PC checkout after closing');
insert into tap_results select lives_ok($$select public.agri_command('register_device',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(12),'name','TEST drawer B'))$$,'A second PC registers without retiring the first');
insert into tap_results select throws_ok($$select public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(11),'openingCash',1000))$$,'P0001','Update this POS app before opening a multiple-PC shift. Saved records must be preserved','Old offline-only clients must update before opening');
insert into tap_results select is(public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(11),'openingCash',1000,'pcProtocol',1))->>'onlineOnly','true','First PC receives online-only authorization');
insert into tap_results select is(public.agri_command('open_shift',pg_temp.ctx()||jsonb_build_object('deviceId',pg_temp.i(12),'openingCash',2000,'pcProtocol',1))->>'onlineOnly','true','Second PC opens its own drawer simultaneously');
insert into tap_results select is((select count(*)::integer from public.cashier_shifts where closed_at is null),2,'Each PC has exactly one separate open shift');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.sale(21,11))$$,'P0001','Multiple-PC checkout requires online confirmation. Update this app and retry the original request; do not re-enter an uncertain sale','Offline record-sale path cannot bypass shared stock confirmation');
insert into tap_results select lives_ok($$select public.agri_command('record_online_sale',pg_temp.sale(21,11))$$,'First drawer confirms a discounted sale');
insert into tap_results select is(public.agri_command('record_online_sale',pg_temp.sale(21,11))->>'status','duplicate','Original online sale retry is idempotent');
insert into tap_results select lives_ok($$select public.agri_command('record_online_sale',pg_temp.sale(22,12))$$,'Second drawer confirms against remaining shared stock');
insert into tap_results select throws_ok($$select public.agri_command('record_online_sale',pg_temp.sale(23,12,'2'))$$,'P0001','Not enough confirmed saleable stock. Refresh and review this basket; no sale was recorded','A stale or repeated-line basket cannot oversell');
insert into tap_results select is((select count(*)::integer from public.sales),2,'Rejected sale has no receipt or financial record');
insert into tap_results select is((select count(*)::integer from public.payments),2,'Rejected and retried sales do not duplicate cash');
insert into tap_results select is((select quantity::text from public.branch_inventory),'1.000000','Shared stock is deducted once for each confirmed sale');
insert into tap_results select throws_ok($$select public.agri_command('configure_cashier_pcs',pg_temp.ctx()||'{"enabled":false,"reason":"TEST mode change"}')$$,'P0001','Close and synchronize every branch shift before changing cashier PC mode','Other open shifts cannot be ignored during mode change');
insert into tap_results select is((select expected_cash from public.cashier_shifts where device_id=pg_temp.i(11) and opening_cash=1000 order by opened_at desc,id desc limit 1),10900::bigint,'Drawer A includes only its own opening cash and net sale');
insert into tap_results select is((select count(*)::integer from public.cashier_shifts where device_id=pg_temp.i(12) and closed_at is null),1,'Closing drawer A leaves drawer B open');
insert into tap_results select is((select expected_cash from public.cashier_shifts where device_id=pg_temp.i(12)),11900::bigint,'Drawer B reconciles independently');
insert into tap_results select throws_ok($$select public.agri_command('configure_cashier_pcs',pg_temp.ctx()||'{"enabled":false,"reason":"TEST mode change"}')$$,'P0001','Retire extra cashier PCs before returning to single-PC mode','Offline mode cannot be enabled with multiple active PCs');
insert into tap_results select * from finish();
